"""Generate comprehensive drugs.json with 50+ realistic drugs."""
import json, unicodedata, os

def norm(t):
    return ''.join(c for c in unicodedata.normalize('NFKD',t) if not unicodedata.combining(c)).lower()

def st(d):
    parts = [d["nombre"],d["nombreGenerico"]," ".join(d["nombresComerciales"]),d["familia"],d["clasificacion"]," ".join(d["indicaciones"])]
    return norm(" ".join(parts))

