{"id":"atenolol","nombre":"Atenolol","nombreGenerico":"Atenolol","nombresComerciales":["Tenormin","Blokium","Atenol"],"familia":"Beta-bloqueantes","clasificacion":"Beta-1 bloqueador selectivo","mecanismoAccion":"Bloquea selectivamente receptores beta-1 adrenérgicos cardíacos, reduciendo frecuencia cardíaca, contractilidad y gasto cardíaco.","indicaciones":["Hipertensión arterial","Angina de pecho estable","Arritmias supraventriculares","Prevención secundaria post-IAM"],"contraindicaciones":["Bradicardia severa (<45 lpm)","Bloqueo AV 2do-3er grado","Insuficiencia cardíaca descompensada","Asma bronquial","Feocromocitoma sin alfa-bloqueo"],"efectosAdversos":["Bradicardia","Fatiga","Extremidades frías","Broncoespasmo","Hipotensión","Depresión","Disfunción eréctil","Enmascaramiento de hipoglucemia"],"interacciones":["Verapamilo/diltiazem: riesgo de bloqueo AV","Insulina: enmascara hipoglucemia","Clonidina: hipertensión de rebote si se suspenden ambos","Digital: potencia bradicardia"],"viaAdministracion":["oral"],"dosis":{"adulto":"HTA: 50-100 mg/día en 1-2 tomas. Angina: 50-200 mg/día","ajusteRenal":"ClCr 15-35: 50 mg/día. ClCr <15: 25 mg/día"},"presentaciones":["Comprimidos 50, 100 mg"],"embarazo":"D","lactancia":"Se excreta en leche. Monitorizar bradicardia en lactante.","cuidadosEnfermeria":["Medir FC ANTES de administrar: no dar si FC <50 lpm","Monitorizar PA: no dar si PAS <90 mmHg","NUNCA suspender bruscamente: riesgo de angina de rebote o IAM","Reducir dosis gradualmente en 1-2 semanas","Educar diabéticos: enmascara taquicardia de hipoglucemia","Vigilar signos de IC: disnea, edema, ganancia de peso"],"farmacocinetica":{"absorcion":"Oral: incompleta, biodisponibilidad 50%","metabolismo":"Mínimo hepático","excrecion":"Renal sin cambios 40-50%","vidaMedia":"6-7 horas","inicioAccion":"1-2 horas","picoAccion":"2-4 horas","duracionAccion":"24 horas"},"unidadId":"u02","capituloId":"c02_01"},
{"id":"amiodarona","nombre":"Amiodarona","nombreGenerico":"Clorhidrato de amiodarona","nombresComerciales":["Cordarone","Trangorex","Atlansil"],"familia":"Antiarrítmicos","clasificacion":"Antiarrítmico clase III (bloqueo canales de potasio)","mecanismoAccion":"Prolonga el potencial de acción y período refractario en todos los tejidos cardíacos. También tiene propiedades de clases I, II y IV.","indicaciones":["Fibrilación auricular","Taquicardia ventricular","Fibrilación ventricular (ACLS)","Arritmias supraventriculares refractarias"],"contraindicaciones":["Bradicardia sinusal severa","Bloqueo AV","Disfunción tiroidea grave","Hipersensibilidad al yodo","Enfermedad pulmonar intersticial"],"efectosAdversos":["Toxicidad pulmonar (fibrosis)","Hipo/hipertiroidismo","Hepatotoxicidad","Fotosensibilidad","Microdepósitos corneales","Neuropatía periférica","Coloración azul-grisácea de piel","Prolongación QT"],"interacciones":["Warfarina: aumenta INR (reducir warfarina 50%)","Digoxina: aumenta niveles (reducir digoxina 50%)","Simvastatina: riesgo miopatía (no exceder 20 mg)","Fenitoína: aumenta niveles de fenitoína"],"viaAdministracion":["oral","IV"],"dosis":{"adulto":"Carga oral: 200 mg TID x 1-2 semanas. Mantenimiento: 200 mg/día. Carga IV: 150 mg en 10 min, luego 1 mg/min x 6h, luego 0.5 mg/min"},"presentaciones":["Comprimidos 200 mg","Ampollas 150 mg/3 mL"],"embarazo":"D","lactancia":"Contraindicada. Alto contenido de yodo.","cuidadosEnfermeria":["Monitorización ECG continua durante carga IV","Infundir por vía central (irrita venas periféricas)","Usar equipo libre de PVC (se adsorbe al plástico)","Vigilar función tiroidea cada 6 meses","Radiografía de tórax basal y cada 6-12 meses","Función hepática cada 6 meses","Examen oftalmológico anual","Protección solar estricta: fotosensibilidad severa","Vida media muy larga: efectos persisten semanas tras suspender"],"farmacocinetica":{"absorcion":"Oral: variable, 22-86%","distribucion":"Muy liposoluble, se acumula en tejidos","metabolismo":"Hepático: CYP3A4, metabolito activo","vidaMedia":"40-55 DÍAS","inicioAccion":"Oral: días a semanas. IV: minutos","duracionAccion":"Semanas tras suspensión"},"almacenamiento":"Temperatura ambiente. Proteger de la luz.","unidadId":"u02","capituloId":"c02_02"},
{"id":"nitroglicerina","nombre":"Nitroglicerina","nombreGenerico":"Trinitrato de glicerilo","nombresComerciales":["Nitrostat","Nitradisc","Solinitrina"],"familia":"Vasodilatadores","clasificacion":"Nitrato orgánico","mecanismoAccion":"Libera óxido nítrico que activa la guanilato ciclasa, aumentando GMPc y produciendo relajación del músculo liso vascular, predominantemente venoso.","indicaciones":["Angina de pecho (tratamiento agudo)","Síndrome coronario agudo","Edema agudo de pulmón","Crisis hipertensiva","Espasmo coronario"],"contraindicaciones":["Uso de inhibidores PDE5 (sildenafilo, tadalafilo) en últimas 24-48h","Hipotensión severa (PAS <90)","Taponamiento cardíaco","IAM de ventrículo derecho"],"efectosAdversos":["Cefalea (muy frecuente)","Hipotensión","Taquicardia refleja","Rubor facial","Mareo","Tolerancia con uso continuo"],"interacciones":["Sildenafilo/tadalafilo: hipotensión potencialmente fatal","Alcohol: potencia hipotensión","Antihipertensivos: efecto aditivo"],"viaAdministracion":["sublingual","IV","transdermica","oral"],"dosis":{"adulto":"SL: 0.4-0.8 mg, repetir cada 5 min (máx 3 dosis). IV: inicio 5 mcg/min, titular cada 5 min. Parche: 0.2-0.8 mg/h"},"presentaciones":["Comprimidos sublinguales 0.6 mg","Spray sublingual 0.4 mg/pulsación","Ampollas 5 mg/mL, 25 mg/5 mL","Parches transdérmicos 5, 10 mg/24h"],"embarazo":"C","lactancia":"Datos insuficientes. Precaución.","cuidadosEnfermeria":["SL: paciente SENTADO (riesgo hipotensión)","SL: si no mejora tras 3 dosis, sospechar IAM → emergencia","IV: usar equipo libre de PVC, titular con PA","Dejar 10-12h libres de nitrato/día (prevenir tolerancia)","Retirar parche 10-12h (generalmente por la noche)","Monitorizar PA continuamente con infusión IV","Cefalea es esperable: indica que el fármaco funciona","NUNCA administrar con sildenafilo o tadalafilo"],"farmacocinetica":{"metabolismo":"Hepático: primer paso extenso (oral)","vidaMedia":"1-4 min (IV)","inicioAccion":"SL: 1-3 min. IV: inmediato. Parche: 30-60 min","duracionAccion":"SL: 30-60 min. IV: durante infusión. Parche: 12h"},"almacenamiento":"SL: frasco oscuro, hermético. Desechar 6 meses después de abrir.","unidadId":"u02","capituloId":"c02_03"},
# === U03 ANTIINFECCIOSOS ===
{"id":"amoxicilina","nombre":"Amoxicilina","nombreGenerico":"Amoxicilina trihidrato","nombresComerciales":["Amoxil","Clamoxyl","Ospamox"],"familia":"Penicilinas","clasificacion":"Aminopenicilina de amplio espectro","mecanismoAccion":"Inhibe la síntesis de pared bacteriana al unirse a proteínas fijadoras de penicilina (PBP), produciendo lisis osmótica bacteriana. Bactericida.","indicaciones":["Infecciones respiratorias superiores e inferiores","Otitis media aguda","Faringoamigdalitis estreptocócica","Infecciones urinarias","Erradicación de H. pylori (triple terapia)","Profilaxis de endocarditis"],"contraindicaciones":["Alergia a penicilinas","Mononucleosis infecciosa (rash)"],"efectosAdversos":["Diarrea","Náuseas","Rash cutáneo","Candidiasis oral/vaginal","Reacción alérgica","Colitis pseudomembranosa (raro)"],"interacciones":["Metotrexato: reduce excreción","Anticoagulantes orales: puede aumentar INR","Alopurinol: mayor riesgo de rash","Anticonceptivos orales: posible reducción eficacia"],"viaAdministracion":["oral"],"dosis":{"adulto":"500 mg cada 8h o 875 mg cada 12h. Dosis alta: 1g cada 8h","pediatrico":"25-50 mg/kg/día dividido cada 8h. Dosis alta: 80-90 mg/kg/día"},"presentaciones":["Cápsulas 500 mg","Comprimidos 875 mg","Suspensión 125 mg/5 mL, 250 mg/5 mL","Amoxicilina/ácido clavulánico: 500/125, 875/125 mg"],"embarazo":"B","lactancia":"Compatible. Se excreta en pequeñas cantidades.","cuidadosEnfermeria":["Preguntar SIEMPRE alergia a penicilina antes de administrar","Completar el tratamiento aunque mejore (resistencia)","Refrigerar suspensión reconstituida (14 días máx)","Vigilar diarrea: puede indicar colitis por C. difficile","Educar: puede tomarse con o sin alimentos","Vigilar signos de alergia: rash, urticaria, anafilaxia"],"farmacocinetica":{"absorcion":"Oral: 75-90%, no afectada por alimentos","distribucion":"Buena penetración en tejidos y fluidos","metabolismo":"Mínimo hepático","excrecion":"Renal 60-70% sin cambios","vidaMedia":"1-1.5 horas","inicioAccion":"30 min","picoAccion":"1-2 horas","duracionAccion":"8 horas"},"unidadId":"u03","capituloId":"c03_01"},
{"id":"ciprofloxacino","nombre":"Ciprofloxacino","nombreGenerico":"Ciprofloxacino","nombresComerciales":["Ciproxina","Cipro","Baycip"],"familia":"Quinolonas","clasificacion":"Fluoroquinolona de segunda generación","mecanismoAccion":"Inhibe la ADN girasa y topoisomerasa IV bacterianas, impidiendo la replicación, transcripción y reparación del ADN bacteriano. Bactericida.","indicaciones":["Infecciones urinarias complicadas","Prostatitis bacteriana","Infecciones gastrointestinales","Infecciones óseas y articulares","Infecciones respiratorias (Gram negativos)","Ántrax (post-exposición)"],"contraindicaciones":["Menores de 18 años (daño cartílago)","Embarazo y lactancia","Uso concomitante de tizanidina","Antecedente de tendinopatía por quinolonas","Epilepsia"],"efectosAdversos":["Náuseas","Diarrea","Cefalea","Tendinitis/rotura tendinosa","Fotosensibilidad","Prolongación QT","Neuropatía periférica","Convulsiones","Aneurisma aórtico (riesgo aumentado)"],"interacciones":["Antiácidos, hierro, calcio: reducen absorción (separar 2h)","Teofilina: aumenta niveles","Warfarina: aumenta INR","AINE: aumentan riesgo convulsiones"],"viaAdministracion":["oral","IV"],"dosis":{"adulto":"Oral: 250-750 mg cada 12h. IV: 200-400 mg cada 12h","ajusteRenal":"ClCr 30-50: 250-500 mg cada 12h. ClCr <30: 250-500 mg cada 18h"},"presentaciones":["Comprimidos 250, 500, 750 mg","Solución IV 2 mg/mL (100, 200 mL)","Colirio 3 mg/mL"],"embarazo":"C","lactancia":"Contraindicada.","cuidadosEnfermeria":["Separar de antiácidos, lácteos y hierro (2h antes o 6h después)","Infundir IV en 60 minutos mínimo","Hidratar bien al paciente (prevenir cristaluria)","Vigilar dolor en tendones (suspender inmediatamente)","Protección solar durante el tratamiento","No administrar en menores de 18 años","Monitorizar ECG si uso concomitante con fármacos que prolongan QT"],"farmacocinetica":{"absorcion":"Oral: 70-80%","metabolismo":"Hepático parcial","excrecion":"Renal 40-50%","vidaMedia":"4-7 horas","inicioAccion":"Oral 1-2h, IV fin de infusión","duracionAccion":"12 horas"},"unidadId":"u03","capituloId":"c03_02"},
{"id":"azitromicina","nombre":"Azitromicina","nombreGenerico":"Azitromicina dihidrato","nombresComerciales":["Zithromax","Azitrocin","Toraseptol"],"familia":"Macrólidos","clasificacion":"Azálido (macrólido de 15 átomos)","mecanismoAccion":"Se une a la subunidad 50S del ribosoma bacteriano, inhibiendo la síntesis proteica. Bacteriostático a dosis normales.","indicaciones":["Neumonía comunitaria","Faringoamigdalitis","Otitis media","Sinusitis","Infecciones de piel","ITS: Chlamydia, gonorrea","Profilaxis MAC en VIH"],"contraindicaciones":["Alergia a macrólidos","Insuficiencia hepática grave","Prolongación QT preexistente"],"efectosAdversos":["Diarrea","Náuseas","Dolor abdominal","Cefalea","Prolongación QT (raro)","Hepatotoxicidad (raro)"],"interacciones":["Warfarina: puede aumentar INR","Digoxina: aumenta niveles","Antiácidos: reducen absorción","Ergotamina: riesgo ergotismo"],"viaAdministracion":["oral","IV"],"dosis":{"adulto":"500 mg día 1, luego 250 mg días 2-5. Alternativa: 500 mg/día x 3 días. Chlamydia: 1g dosis única","pediatrico":"10 mg/kg día 1, luego 5 mg/kg días 2-5"},"presentaciones":["Comprimidos 500 mg","Cápsulas 250 mg","Suspensión 200 mg/5 mL","Polvo para solución IV 500 mg"],"embarazo":"B","lactancia":"Compatible con precaución.","cuidadosEnfermeria":["Tomar 1h antes o 2h después de alimentos (comprimidos)","Suspensión puede tomarse con alimentos","Verificar adherencia en tratamientos cortos (3-5 días)","Vida media larga: efecto persiste 5 días tras última dosis","Vigilar diarrea y dolor abdominal","IV: infundir en mínimo 60 min (nunca en bolo)"],"farmacocinetica":{"absorcion":"Oral: 37%, reducida por alimentos","distribucion":"Excelente penetración tisular (concentración tisular >> plasmática)","metabolismo":"Hepático mínimo","excrecion":"Biliar (principal)","vidaMedia":"68 horas (tisular)","inicioAccion":"2-3 horas","duracionAccion":"Efecto persiste 5-7 días post-tratamiento"},"unidadId":"u03","capituloId":"c03_02"},
{"id":"vancomicina","nombre":"Vancomicina","nombreGenerico":"Clorhidrato de vancomicina","nombresComerciales":["Vancocin","Vancomicina Hospira"],"familia":"Glucopéptidos","clasificacion":"Antibiótico glucopéptido","mecanismoAccion":"Inhibe la síntesis de pared celular bacteriana al unirse al dipéptido D-alanil-D-alanina, impidiendo la polimerización del peptidoglucano.","indicaciones":["Infecciones graves por SARM","Endocarditis por enterococo/estafilococo","Meningitis bacteriana (coadyuvante)","Colitis por C. difficile (oral)","Infecciones en alérgicos a betalactámicos"],"contraindicaciones":["Alergia a vancomicina"],"efectosAdversos":["Síndrome del hombre rojo (infusión rápida)","Nefrotoxicidad","Ototoxicidad","Flebitis","Neutropenia","Trombocitopenia"],"interacciones":["Aminoglucósidos: potencia nefro y ototoxicidad","Anestésicos: mayor riesgo histamina","Colestiramina: reduce efecto oral"],"viaAdministracion":["IV","oral"],"dosis":{"adulto":"IV: 15-20 mg/kg cada 8-12h (guiado por niveles). Oral (C. difficile): 125-500 mg cada 6h","ajusteRenal":"Guiar por niveles séricos (valle 15-20 mcg/mL para infecciones graves)"},"presentaciones":["Polvo para reconstitución IV 500 mg, 1 g","Cápsulas 125, 250 mg (oral)"],"embarazo":"C","lactancia":"Precaución. Monitorizar lactante.","cuidadosEnfermeria":["Infundir en MÍNIMO 60 min por cada gramo (prevenir síndrome del hombre rojo)","Monitorizar niveles séricos: valle antes de 4ta dosis","Vigilar función renal y auditiva","Si rash/rubor durante infusión: detener, antihistamínico, reiniciar más lento","Oral NO se absorbe: solo útil para infecciones GI","IV NO útil para colitis por C. difficile","Verificar sitio IV: vesicante, causa necrosis si extravasa"],"farmacocinetica":{"distribucion":"Buena penetración tisular excepto SNC (mejora con meninges inflamadas)","excrecion":"Renal 90%","vidaMedia":"4-6 horas (normal), hasta 7 días (anuria)"},"almacenamiento":"Reconstitución: estable 14 días refrigerado.","unidadId":"u03","capituloId":"c03_03"},
{"id":"metronidazol","nombre":"Metronidazol","nombreGenerico":"Metronidazol","nombresComerciales":["Flagyl","Metrogyl","Rozex"],"familia":"Nitroimidazoles","clasificacion":"Antiprotozoario y antibacteriano anaerobicida","mecanismoAccion":"Se reduce intracelularmente a metabolitos que dañan el ADN bacteriano, causando muerte celular. Activo contra anaerobios y protozoarios.","indicaciones":["Infecciones por anaerobios","Colitis por C. difficile (alternativa)","Amebiasis","Giardiasis","Tricomoniasis","Vaginosis bacteriana","Infecciones intraabdominales (combinado)"],"contraindicaciones":["Primer trimestre de embarazo","Uso concomitante de alcohol","Uso de disulfiram"],"efectosAdversos":["Náuseas y sabor metálico","Neuropatía periférica (uso prolongado)","Convulsiones (dosis altas)","Orina oscura (inofensivo)","Reacción tipo disulfiram con alcohol"],"interacciones":["Alcohol: reacción tipo disulfiram (rubor, vómitos, taquicardia)","Warfarina: aumenta efecto anticoagulante","Litio: aumenta toxicidad","Fenitoína: niveles alterados"],"viaAdministracion":["oral","IV","topica","vaginal"],"dosis":{"adulto":"500 mg cada 8h oral/IV. Amebiasis: 750 mg TID x 7-10 días. C. difficile: 500 mg TID x 10-14 días","pediatrico":"7.5 mg/kg/dosis cada 8h"},"presentaciones":["Comprimidos 250, 500 mg","Solución IV 5 mg/mL (100 mL)","Óvulos vaginales 500 mg","Gel tópico 0.75%"],"embarazo":"B","lactancia":"Se excreta en leche. Suspender lactancia durante tratamiento y 24h después.","cuidadosEnfermeria":["PROHIBIR alcohol durante el tratamiento y 48h después","Educar sobre orina oscura (no alarmar)","Infundir IV en 30-60 minutos","Vigilar neuropatía: hormigueo, entumecimiento","No triturar comprimidos de liberación prolongada","Completar esquema completo de tratamiento"],"farmacocinetica":{"absorcion":"Oral: casi completa","metabolismo":"Hepático","excrecion":"Renal 60-80%","vidaMedia":"6-8 horas","inicioAccion":"Oral: 1-2 horas"},"unidadId":"u03","capituloId":"c03_03"},
# === U04 RESPIRATORIO ===
{"id":"salbutamol","nombre":"Salbutamol (Albuterol)","nombreGenerico":"Sulfato de salbutamol","nombresComerciales":["Ventolin","Aerosal","Salamol"],"familia":"Broncodilatadores","clasificacion":"Agonista beta-2 adrenérgico de acción corta (SABA)","mecanismoAccion":"Estimula receptores beta-2 del músculo liso bronquial, activando adenilato ciclasa y aumentando AMPc, produciendo relajación bronquial.","indicaciones":["Broncoespasmo agudo","Asma (rescate)","EPOC (rescate)","Prevención broncoespasmo por ejercicio","Hiperpotasemia (coadyuvante)"],"contraindicaciones":["Hipersensibilidad"],"efectosAdversos":["Temblor fino de manos","Taquicardia","Palpitaciones","Cefalea","Hipopotasemia","Calambres musculares","Nerviosismo"],"interacciones":["Beta-bloqueantes: antagonizan efecto","Diuréticos: potencian hipopotasemia","Digoxina: riesgo arritmias por hipopotasemia","IMAO: riesgo cardiovascular"],"viaAdministracion":["inhalatoria","oral","IV","SC"],"dosis":{"adulto":"IDM: 2 puffs (200 mcg) cada 4-6h PRN. Nebulización: 2.5-5 mg cada 4-6h. Crisis: nebulización cada 20 min x3","pediatrico":"IDM: 2 puffs con aerocámara. Nebulización: 0.15 mg/kg (mín 2.5 mg)"},"presentaciones":["IDM 100 mcg/dosis","Solución para nebulización 5 mg/mL","Jarabe 2 mg/5 mL","Comprimidos 2, 4 mg"],"embarazo":"C","lactancia":"Probablemente compatible.","cuidadosEnfermeria":["Enseñar técnica inhalatoria correcta (80% la realizan mal)","Siempre usar aerocámara en niños","Si usa con corticoide inhalado: salbutamol PRIMERO","Máximo efecto a los 15-30 min post-inhalación","Si necesita >2 veces/semana: asma mal controlada → derivar","Nebulización: flujo 6-8 L/min por 10-15 min","Monitorizar FC y potasio en uso frecuente"],"farmacocinetica":{"absorcion":"Inhalatoria: 10-20% llega a pulmones","metabolismo":"Hepático","vidaMedia":"2-7 horas","inicioAccion":"Inhalado: 5-15 min. Nebulizado: 5 min","picoAccion":"30-60 min","duracionAccion":"4-6 horas"},"unidadId":"u04","capituloId":"c04_01"},
{"id":"budesonida","nombre":"Budesonida","nombreGenerico":"Budesonida","nombresComerciales":["Pulmicort","Symbicort (combinado)","Rhinocort"],"familia":"Corticoides inhalados","clasificacion":"Glucocorticoide sintético para inhalación","mecanismoAccion":"Actúa sobre receptores glucocorticoides intracelulares, reduciendo la inflamación bronquial al inhibir mediadores proinflamatorios y reducir edema mucoso.","indicaciones":["Asma persistente (mantenimiento)","EPOC (combinado con broncodilatador)","Rinitis alérgica (nasal)","Laringitis subglótica (nebulizado)"],"contraindicaciones":["No usar como rescate en crisis aguda","Infección fúngica sistémica activa"],"efectosAdversos":["Candidiasis orofaríngea","Disfonía","Tos","Infecciones respiratorias","Supresión adrenal (dosis altas crónicas)","Retraso del crecimiento en niños (mínimo)"],"interacciones":["CYP3A4 inhibidores (ketoconazol, ritonavir): aumentan niveles","Formoterol (en combinación): efecto sinérgico"],"viaAdministracion":["inhalatoria","nasal"],"dosis":{"adulto":"Asma leve: 200-400 mcg/día. Moderada: 400-800 mcg/día. Severa: 800-1600 mcg/día","pediatrico":"100-400 mcg/día. Nebulización: 0.25-1 mg cada 12h"},"presentaciones":["IDM 200 mcg/dosis","IPS Turbuhaler 100, 200, 400 mcg","Suspensión nebulización 0.25, 0.5 mg/mL","Spray nasal 64 mcg/dosis"],"embarazo":"B","lactancia":"Compatible en dosis terapéuticas inhaladas.","cuidadosEnfermeria":["ENJUAGAR BOCA después de cada inhalación (prevenir candidiasis)","No es medicamento de rescate: efecto tarda días-semanas","Enseñar diferencia entre controlador y rescate","Verificar técnica inhalatoria en cada consulta","Monitorizar crecimiento en niños con uso crónico","Revisar dosis periódicamente: usar dosis mínima efectiva"],"farmacocinetica":{"absorcion":"Inhalatoria: 15-30% deposición pulmonar","metabolismo":"Hepático: CYP3A4, extenso primer paso","vidaMedia":"2-3 horas","inicioAccion":"24-48 horas (efecto antiinflamatorio)","picoAccion":"1-2 semanas para efecto máximo"},"unidadId":"u04","capituloId":"c04_02"},
# === U05 DIGESTIVO ===
{"id":"omeprazol","nombre":"Omeprazol","nombreGenerico":"Omeprazol","nombresComerciales":["Losec","Prilosec","Omepral"],"familia":"Inhibidores de bomba de protones","clasificacion":"IBP - antisecretor gástrico","mecanismoAccion":"Inhibe irreversiblemente la bomba H+/K+ ATPasa en la célula parietal gástrica, bloqueando la secreción ácida de forma potente y prolongada.","indicaciones":["Úlcera gástrica y duodenal","ERGE","Erradicación H. pylori (triple terapia)","Síndrome de Zollinger-Ellison","Profilaxis de úlcera por AINEs","Hemorragia digestiva alta"],"contraindicaciones":["Hipersensibilidad a IBP"],"efectosAdversos":["Cefalea","Diarrea","Dolor abdominal","Náuseas","Deficiencia B12 y magnesio (uso crónico)","Mayor riesgo infecciones: C. difficile, neumonía","Osteoporosis (uso prolongado)","Nefritis intersticial (raro)"],"interacciones":["Clopidogrel: reduce activación (evitar combinación)","Metotrexato: aumenta niveles","Ketoconazol: reduce absorción","Diazepam: aumenta niveles"],"viaAdministracion":["oral","IV"],"dosis":{"adulto":"Úlcera/ERGE: 20-40 mg/día. H. pylori: 20 mg BID + 2 antibióticos. HDA: 80 mg bolo IV + 8 mg/h infusión","pediatrico":"1 mg/kg/día (máx 20 mg/día)"},"presentaciones":["Cápsulas 20, 40 mg","Polvo para suspensión oral","Polvo para inyección IV 40 mg"],"embarazo":"C","lactancia":"Se excreta en leche. Evaluar riesgo/beneficio.","cuidadosEnfermeria":["Tomar 30-60 minutos ANTES del desayuno","No triturar ni masticar cápsulas (recubrimiento entérico)","IV: reconstituir con SF, infundir en 20-30 min","Revisar necesidad de uso crónico: no usar indefinidamente","Vigilar niveles de magnesio en uso >1 año","Evaluar interacción con clopidogrel"],"farmacocinetica":{"absorcion":"Oral: rápida, biodisponibilidad 30-40% (aumenta con dosis repetidas)","metabolismo":"Hepático: CYP2C19 y CYP3A4","vidaMedia":"0.5-1 hora","inicioAccion":"1 hora","duracionAccion":"72 horas (inhibición irreversible)"},"unidadId":"u05","capituloId":"c05_01"},
{"id":"metoclopramida","nombre":"Metoclopramida","nombreGenerico":"Clorhidrato de metoclopramida","nombresComerciales":["Primperan","Reliveran","Reglan"],"familia":"Procinéticos/Antieméticos","clasificacion":"Antagonista dopaminérgico D2 central y periférico","mecanismoAccion":"Bloquea receptores D2 en zona gatillo quimiorreceptora (efecto antiemético) y estimula motilidad GI superior (efecto procinético).","indicaciones":["Náuseas y vómitos","Gastroparesia diabética","Reflujo gastroesofágico","Profilaxis de náuseas postquirúrgicas","Facilitación de intubación nasogástrica"],"contraindicaciones":["Obstrucción intestinal mecánica","Feocromocitoma","Epilepsia","Hemorragia GI","Uso con fármacos que causan extrapiramidalismo"],"efectosAdversos":["Somnolencia","Reacciones extrapiramidales (distonía aguda)","Discinesia tardía (uso crónico)","Galactorrea","Amenorrea","Síndrome neuroléptico maligno (raro)"],"interacciones":["Antipsicóticos: efectos extrapiramidales aditivos","Levodopa: reduce efecto antiparkinsoniano","Opioides: antagoniza procinesia","Alcohol: potencia sedación"],"viaAdministracion":["oral","IV","IM"],"dosis":{"adulto":"10 mg 3-4 veces/día (30 min antes de comidas). IV: 10 mg lento. Máx: 0.5 mg/kg/día. Máx 5 días","pediatrico":"0.1-0.15 mg/kg/dosis (máx 3 veces/día)"},"presentaciones":["Comprimidos 10 mg","Gotas 4 mg/mL","Ampollas 10 mg/2 mL"],"embarazo":"B","lactancia":"Se excreta en leche. Precaución.","cuidadosEnfermeria":["Administrar 30 min ANTES de comidas","IV: administrar lento (1-2 min) para evitar reacciones extrapiramidales","No usar >5 días sin evaluación médica","Vigilar distonía aguda: tortícolis, trismus, crisis oculógira","Antídoto de distonía: difenhidramina IV","Especial precaución en jóvenes y ancianos (más sensibles)","No usar prolongadamente: riesgo discinesia tardía irreversible"],"farmacocinetica":{"absorcion":"Oral: rápida, biodisponibilidad 80%","metabolismo":"Hepático","excrecion":"Renal 85%","vidaMedia":"4-6 horas","inicioAccion":"Oral: 30-60 min. IV: 1-3 min","duracionAccion":"1-2 horas"},"unidadId":"u05","capituloId":"c05_02"},
{"id":"ondansetron","nombre":"Ondansetrón","nombreGenerico":"Clorhidrato de ondansetrón","nombresComerciales":["Zofran","Ondax","Modifical"],"familia":"Antieméticos","clasificacion":"Antagonista selectivo de receptores 5-HT3 de serotonina","mecanismoAccion":"Bloquea receptores 5-HT3 en la zona gatillo quimiorreceptora y en nervios vagales aferentes del tracto GI.","indicaciones":["Náuseas y vómitos por quimioterapia","Náuseas y vómitos postoperatorios","Náuseas por radioterapia","Náuseas del embarazo (hiperemesis gravídica)"],"contraindicaciones":["Hipersensibilidad","Uso con apomorfina","Prolongación QT congénita"],"efectosAdversos":["Cefalea","Estreñimiento","Prolongación QT","Mareo","Fatiga"],"interacciones":["Apomorfina: hipotensión severa","Tramadol: reduce efecto analgésico","Fármacos que prolongan QT: precaución"],"viaAdministracion":["oral","IV","IM"],"dosis":{"adulto":"4-8 mg IV/oral previo a quimioterapia/cirugía. Postop: 4 mg IV","pediatrico":"0.15 mg/kg IV (máx 4 mg/dosis)"},"presentaciones":["Comprimidos 4, 8 mg","Comprimidos bucodispersables 4, 8 mg","Ampollas 4 mg/2 mL, 8 mg/4 mL"],"embarazo":"B","lactancia":"Datos limitados. Precaución.","cuidadosEnfermeria":["Administrar 30 min antes de quimioterapia","IV: infundir en 15 min (no bolo rápido por riesgo QT)","No produce sedación ni extrapiramidalismo (ventaja sobre metoclopramida)","Puede causar estreñimiento: vigilar patrón intestinal","Monitorizar ECG en pacientes con riesgo de prolongación QT"],"farmacocinetica":{"metabolismo":"Hepático: CYP3A4, CYP1A2, CYP2D6","vidaMedia":"3-5 horas","inicioAccion":"IV: 5-10 min. Oral: 30 min","duracionAccion":"4-8 horas"},"unidadId":"u05","capituloId":"c05_02"},
# === U06 ENDOCRINO ===
{"id":"insulina_regular","nombre":"Insulina Regular (Cristalina)","nombreGenerico":"Insulina humana regular","nombresComerciales":["Humulin R","Actrapid","Novolin R"],"familia":"Insulinas","clasificacion":"Insulina de acción rápida","mecanismoAccion":"Se une a receptores de insulina, facilitando la captación celular de glucosa, estimulando glucogénesis y lipogénesis, e inhibiendo gluconeogénesis.","indicaciones":["Diabetes mellitus tipo 1 y 2","Cetoacidosis diabética","Estado hiperosmolar","Hiperpotasemia (con glucosa)","Control glucémico perioperatorio"],"contraindicaciones":["Hipoglucemia","Hipersensibilidad"],"efectosAdversos":["Hipoglucemia (principal)","Lipodistrofia en sitio de inyección","Hipopotasemia","Aumento de peso","Reacciones locales"],"interacciones":["Beta-bloqueantes: enmascaran hipoglucemia","Corticoides: antagonizan efecto","Tiazolidinedionas: potencian efecto","Alcohol: riesgo hipoglucemia"],"viaAdministracion":["SC","IV"],"dosis":{"adulto":"SC: 0.1-0.2 UI/kg/dosis antes de comidas (individualizar). CAD: 0.1 UI/kg/h en infusión continua IV. Hiperpotasemia: 10 UI + 25g glucosa IV","pediatrico":"SC: 0.5-1 UI/kg/día total (dividir basal/bolo)"},"presentaciones":["Vial 100 UI/mL (10 mL)","Cartuchos para pluma 100 UI/mL (3 mL)","Solución IV"],"embarazo":"B","lactancia":"Compatible. Ajustar dosis según glucemias.","cuidadosEnfermeria":["ÚNICA insulina que puede administrarse IV","Verificar glucemia capilar ANTES de cada dosis","SC: rotar sitios de inyección (prevenir lipodistrofia)","No mezclar en jeringa con insulina glargina","Refrigerar vial en uso 28 días máx a temperatura ambiente","En infusión IV: monitorizar glucemia cada hora","Educar signos de hipoglucemia: temblor, sudoración, confusión","Tener glucosa oral o dextrosa IV disponible","Los 5 correctos de la insulina: tipo, dosis, hora, técnica, sitio"],"farmacocinetica":{"inicioAccion":"SC: 30-60 min. IV: inmediato","picoAccion":"SC: 2-4 horas. IV: 15-30 min","duracionAccion":"SC: 6-8 horas. IV: durante infusión"},"almacenamiento":"Refrigerar 2-8°C. En uso: temperatura ambiente máx 28 días.","unidadId":"u06","capituloId":"c06_01"},
{"id":"metformina","nombre":"Metformina","nombreGenerico":"Clorhidrato de metformina","nombresComerciales":["Glucophage","Dabex","Dianben"],"familia":"Biguanidas","clasificacion":"Antidiabético oral - sensibilizador de insulina","mecanismoAccion":"Reduce la producción hepática de glucosa, mejora la sensibilidad periférica a la insulina y disminuye la absorción intestinal de glucosa. No estimula secreción de insulina.","indicaciones":["Diabetes mellitus tipo 2 (primera línea)","Prediabetes","Síndrome de ovario poliquístico","Resistencia a la insulina"],"contraindicaciones":["Insuficiencia renal grave (TFG <30)","Insuficiencia hepática grave","Insuficiencia cardíaca descompensada","Acidosis metabólica","Alcoholismo activo","48h antes/después de contraste yodado"],"efectosAdversos":["Diarrea","Náuseas","Dolor abdominal","Sabor metálico","Deficiencia de vitamina B12 (largo plazo)","Acidosis láctica (rara pero grave)"],"interacciones":["Alcohol: riesgo acidosis láctica","Contrastes yodados: suspender 48h antes","Cimetidina: aumenta niveles","Corticoides: antagonizan efecto"],"viaAdministracion":["oral"],"dosis":{"adulto":"Inicio: 500 mg con cena. Titular cada 1-2 semanas. Mantenimiento: 1500-2000 mg/día en 2-3 tomas. Máx: 2550 mg/día","ajusteRenal":"TFG 30-45: máx 1000 mg/día. TFG <30: contraindicada"},"presentaciones":["Comprimidos 500, 850, 1000 mg","Comprimidos LP 500, 750, 1000 mg"],"embarazo":"B","lactancia":"Se excreta en leche en mínimas cantidades. Generalmente compatible.","cuidadosEnfermeria":["Tomar CON alimentos (reduce GI adversos)","Iniciar dosis baja y titular gradualmente","Suspender 48h antes de contraste yodado y 48h después","Monitorizar función renal al menos anualmente","Vigilar signos de acidosis láctica: malestar, dolor muscular, disnea","Monitorizar B12 anualmente en uso crónico","NO causa hipoglucemia en monoterapia","Educar: este fármaco no engorda (ventaja sobre otros antidiabéticos)"],"farmacocinetica":{"absorcion":"Oral: 50-60%","metabolismo":"No se metaboliza","excrecion":"Renal sin cambios","vidaMedia":"4-8 horas","inicioAccion":"Días (efecto clínico gradual)","duracionAccion":"8-12 horas"},"unidadId":"u06","capituloId":"c06_01"},
{"id":"levotiroxina","nombre":"Levotiroxina","nombreGenerico":"Levotiroxina sódica (T4)","nombresComerciales":["Eutirox","Synthroid","Levothroid"],"familia":"Hormonas tiroideas","clasificacion":"Hormona tiroidea sintética","mecanismoAccion":"Reemplaza la hormona tiroidea T4 endógena. Se convierte periféricamente a T3 (forma activa), regulando metabolismo basal, termogénesis y desarrollo.","indicaciones":["Hipotiroidismo","Supresión de TSH en cáncer de tiroides","Coma mixedematoso","Bocio no tóxico"],"contraindicaciones":["Tirotoxicosis no tratada","Insuficiencia adrenal no corregida","IAM reciente"],"efectosAdversos":["Síntomas de hipertiroidismo en sobredosis: taquicardia, temblor, sudoración","Pérdida de peso","Insomnio","Osteoporosis (supresión crónica de TSH)","Arritmias cardíacas"],"interacciones":["Calcio, hierro, antiácidos: reducen absorción (separar 4h)","Warfarina: aumenta efecto anticoagulante","Colestiramina: reduce absorción","Fenitoína: altera niveles"],"viaAdministracion":["oral","IV"],"dosis":{"adulto":"Inicio: 25-50 mcg/día (jóvenes: 1.6 mcg/kg/día). Titular cada 4-6 semanas según TSH","geriatrico":"Inicio: 12.5-25 mcg/día. Titular lentamente","pediatrico":"Neonatos: 10-15 mcg/kg/día"},"presentaciones":["Comprimidos 25, 50, 75, 88, 100, 112, 125, 150, 200 mcg"],"embarazo":"A","lactancia":"Se excreta en leche. Compatible. Mantener tratamiento.","cuidadosEnfermeria":["Tomar en AYUNAS, 30-60 min antes del desayuno","Separar de calcio, hierro, antiácidos por 4 horas","No cambiar entre marcas sin supervisión (bioequivalencia variable)","Controlar TSH cada 4-6 semanas hasta estabilizar","Monitorizar FC y PA (especialmente en ancianos y cardiópatas)","Educar: tratamiento de POR VIDA en hipotiroidismo","Vigilar signos de sobredosis: taquicardia, nerviosismo, pérdida de peso"],"farmacocinetica":{"absorcion":"Oral: 40-80% (mejor en ayunas)","metabolismo":"Desyodación periférica a T3","vidaMedia":"6-7 días","inicioAccion":"3-5 días","picoAccion":"4-6 semanas para efecto completo"},"almacenamiento":"Temperatura ambiente. Proteger de luz y humedad.","unidadId":"u06","capituloId":"c06_02"},
