{"id":"ibuprofeno","nombre":"Ibuprofeno","nombreGenerico":"Ibuprofeno","nombresComerciales":["Motrin","Advil","Nurofen","Actron"],"familia":"AINEs","clasificacion":"Antiinflamatorio no esteroideo - derivado del ácido propiónico","mecanismoAccion":"Inhibe las enzimas ciclooxigenasa 1 y 2 (COX-1/COX-2), reduciendo la síntesis de prostaglandinas proinflamatorias, del dolor y de la fiebre.","indicaciones":["Dolor leve a moderado","Fiebre","Inflamación","Dismenorrea","Artritis reumatoide","Artrosis","Dolor dental"],"contraindicaciones":["Úlcera péptica activa","Insuficiencia renal grave","Tercer trimestre de embarazo","Insuficiencia cardíaca grave","Antecedente de sangrado GI por AINEs","Alergia a AINEs o aspirina"],"efectosAdversos":["Dispepsia","Úlcera GI y hemorragia","Nefrotoxicidad","Retención de líquidos","Hipertensión","Reacciones alérgicas","Broncoespasmo en asmáticos sensibles","Riesgo cardiovascular (uso crónico)"],"interacciones":["Anticoagulantes: aumenta riesgo sangrado","IECA/ARA-II: reduce efecto y riesgo renal","Metotrexato: aumenta toxicidad","Litio: aumenta niveles","Corticoides: potencia riesgo GI"],"viaAdministracion":["oral","IV","topica"],"dosis":{"adulto":"200-400 mg cada 6-8h. Máx: 1200 mg/día (OTC), 2400 mg/día (prescripción)","pediatrico":"5-10 mg/kg/dosis cada 6-8h. Máx: 40 mg/kg/día"},"presentaciones":["Comprimidos 200, 400, 600 mg","Suspensión 100 mg/5 mL","Gel tópico 5%"],"embarazo":"C","lactancia":"Compatible a dosis bajas y por cortos periodos.","cuidadosEnfermeria":["Administrar CON alimentos o leche (proteger estómago)","Usar la dosis mínima efectiva por el menor tiempo","No combinar con otros AINEs","Vigilar función renal y hepática en uso prolongado","Monitorizar PA: puede retener líquidos y aumentar PA","Vigilar signos de sangrado GI: heces negras, hematemesis","Precaución en asmáticos: puede precipitar broncoespasmo","Contraindicado en 3er trimestre: cierre prematuro del ductus"],"farmacocinetica":{"absorcion":"Oral: rápida y completa","metabolismo":"Hepático: CYP2C9","excrecion":"Renal 90%","vidaMedia":"2-4 horas","inicioAccion":"30-60 min","picoAccion":"1-2 horas","duracionAccion":"4-6 horas"},"unidadId":"u08","capituloId":"c08_01"},
