{"id":"heparina","nombre":"Heparina No Fraccionada","nombreGenerico":"Heparina sódica","nombresComerciales":["Heparina Leo","Liquemine"],"familia":"Anticoagulantes","clasificacion":"Anticoagulante parenteral - activador de antitrombina III","mecanismoAccion":"Se une a antitrombina III, potenciando 1000 veces su capacidad de inactivar trombina (IIa) y factor Xa, inhibiendo la formación y extensión de trombos.","indicaciones":["Tromboembolismo venoso (tratamiento y profilaxis)","Embolia pulmonar","Síndrome coronario agudo","Circulación extracorpórea","CID (coagulación intravascular diseminada)","Profilaxis en cirugía"],"contraindicaciones":["Sangrado activo","Trombocitopenia inducida por heparina (HIT)","Hemofilia","Úlcera péptica activa","Hipertensión grave no controlada"],"efectosAdversos":["Hemorragia (principal)","Trombocitopenia inducida por heparina (HIT) tipo I y II","Osteoporosis (uso prolongado)","Hiperpotasemia","Alopecia"],"interacciones":["Anticoagulantes orales: efecto aditivo","AINEs: aumentan riesgo sangrado","Antiplaquetarios: efecto aditivo","Nitroglicerina IV: puede reducir efecto de heparina"],"viaAdministracion":["IV","SC"],"dosis":{"adulto":"Terapéutica: bolo 80 UI/kg IV + 18 UI/kg/h infusión (ajustar por TTPa). Profiláctica: 5000 UI SC cada 8-12h","pediatrico":"Bolo 75 UI/kg + 20 UI/kg/h infusión"},"presentaciones":["Viales 1000, 5000, 10000, 25000 UI/mL","Jeringas prellenadas para profilaxis"],"embarazo":"C","lactancia":"No se excreta en leche. Compatible.","cuidadosEnfermeria":["Monitorizar TTPa cada 6h hasta estabilizar (objetivo 1.5-2.5 veces el control)","Tener PROTAMINA disponible como antídoto","Vigilar signos de sangrado: encías, hematuria, petequias, heces negras","Recuento plaquetario basal y cada 2-3 días (vigilar HIT)","SC: inyectar en abdomen, no aspirar, no masajear post-inyección","IV: usar bomba de infusión siempre","No administrar IM","Educar: evitar traumatismos, usar cepillo dental suave"],"farmacocinetica":{"inicioAccion":"IV: inmediato. SC: 20-30 min","picoAccion":"SC: 2-4 horas","vidaMedia":"1-2 horas (dosis dependiente)","duracionAccion":"IV: durante infusión. SC: 8-12 horas"},"almacenamiento":"Temperatura ambiente.","unidadId":"u10","capituloId":"c10_01"},
{"id":"enoxaparina","nombre":"Enoxaparina","nombreGenerico":"Enoxaparina sódica","nombresComerciales":["Clexane","Lovenox"],"familia":"Heparinas de bajo peso molecular","clasificacion":"HBPM - anticoagulante anti-Xa predominante","mecanismoAccion":"Potencia la antitrombina III con mayor actividad anti-Xa que anti-IIa (relación 3.8:1), proporcionando anticoagulación más predecible.","indicaciones":["Profilaxis TVP en cirugía","Tratamiento TVP/TEP","Síndrome coronario agudo","Profilaxis en inmovilización"],"contraindicaciones":["Sangrado activo","Trombocitopenia por heparina","Endocarditis bacteriana aguda"],"efectosAdversos":["Hemorragia","Hematoma en sitio de inyección","Trombocitopenia","Elevación de transaminasas","Osteoporosis (menor que HNF)"],"interacciones":["AINEs: riesgo sangrado","Anticoagulantes orales: efecto aditivo","Antiplaquetarios: riesgo hemorrágico"],"viaAdministracion":["SC"],"dosis":{"adulto":"Profilaxis: 40 mg SC/día. Tratamiento: 1 mg/kg cada 12h o 1.5 mg/kg cada 24h","ajusteRenal":"ClCr <30: 30 mg/día profilaxis, 1 mg/kg/día tratamiento"},"presentaciones":["Jeringas prellenadas 20, 40, 60, 80, 100 mg"],"embarazo":"B","lactancia":"No se excreta significativamente. Compatible.","cuidadosEnfermeria":["SC en abdomen: alternar lados, 5 cm del ombligo","NO expulsar burbuja de aire de la jeringa (es parte del sistema)","No masajear después de inyección","No monitorizar TTPa rutinariamente (predecible)","Anti-Xa solo en obesidad, embarazo, insuficiencia renal","Vigilar plaquetas semanalmente las primeras 3 semanas","Antídoto parcial: protamina (60-75% neutralización)"],"farmacocinetica":{"absorcion":"SC: biodisponibilidad >90%","vidaMedia":"4-5 horas","inicioAccion":"20 min","picoAccion":"3-5 horas","duracionAccion":"12-24 horas"},"almacenamiento":"Temperatura ambiente.","unidadId":"u10","capituloId":"c10_01"},
{"id":"warfarina","nombre":"Warfarina","nombreGenerico":"Warfarina sódica","nombresComerciales":["Coumadin","Aldocumar","Sintrom (acenocumarol)"],"familia":"Anticoagulantes orales","clasificacion":"Antagonista de vitamina K","mecanismoAccion":"Inhibe la enzima vitamina K epóxido reductasa, impidiendo la síntesis de factores de coagulación II, VII, IX y X dependientes de vitamina K.","indicaciones":["Fibrilación auricular (prevención embolismo)","Prótesis valvulares mecánicas","TVP/TEP (mantenimiento)","Prevención de ACV"],"contraindicaciones":["Embarazo","Sangrado activo","Hipertensión maligna","Cirugía reciente del SNC"],"efectosAdversos":["Hemorragia (principal)","Necrosis cutánea (inicio sin heparina)","Alopecia","Osteoporosis","Síndrome del dedo azul"],"interacciones":["Múltiples interacciones: el fármaco con MÁS interacciones conocidas","Amiodarona, fluconazol, metronidazol: aumentan INR","Rifampicina, carbamazepina: disminuyen INR","Vitamina K (alimentos): antagoniza efecto","AINEs: aumentan riesgo sangrado"],"viaAdministracion":["oral"],"dosis":{"adulto":"Inicio: 2-5 mg/día. Ajustar según INR (objetivo 2-3 en mayoría). Prótesis mecánica: INR 2.5-3.5"},"presentaciones":["Comprimidos 1, 2, 2.5, 3, 5, 7.5, 10 mg"],"embarazo":"X","lactancia":"Compatible.","cuidadosEnfermeria":["Monitorizar INR regularmente (semanal al inicio, luego mensual)","Rango terapéutico INR: generalmente 2-3","Antídoto: Vitamina K (IV para urgencia, oral para ajustes)","Educar sobre dieta: mantener ingesta CONSTANTE de vitamina K","Educar interacciones: informar a TODOS los profesionales de salud","Vigilar sangrados: encías, hematuria, equimosis","Instruir: si olvida una dosis, NO duplicar","Evitar deportes de contacto y actividades de riesgo","Usar brazalete de alerta médica"],"farmacocinetica":{"absorcion":"Oral: rápida y completa","metabolismo":"Hepático: CYP2C9, CYP3A4, CYP1A2","vidaMedia":"20-60 horas","inicioAccion":"24 horas (efecto anticoagulante: 2-7 días)","duracionAccion":"2-5 días después de suspender"},"unidadId":"u10","capituloId":"c10_01"},
