{"id":"naloxona","nombre":"Naloxona","nombreGenerico":"Clorhidrato de naloxona","nombresComerciales":["Narcan","Naloxone"],"familia":"Antídotos","clasificacion":"Antagonista opioide puro","mecanismoAccion":"Antagonista competitivo de receptores opioides mu, kappa y delta. Desplaza a los opioides de sus receptores, revirtiendo completamente sus efectos.","indicaciones":["Sobredosis de opioides","Reversión de depresión respiratoria por opioides","Diagnóstico de dependencia a opioides","Coma de origen desconocido (prueba diagnóstica)"],"contraindicaciones":["Hipersensibilidad"],"efectosAdversos":["Síndrome de abstinencia agudo en dependientes","Taquicardia","Hipertensión","Náuseas y vómitos","Edema pulmonar (raro)","Arritmias"],"interacciones":["Opioides: antagonismo completo"],"viaAdministracion":["IV","IM","SC","nasal"],"dosis":{"adulto":"0.4-2 mg IV, repetir cada 2-3 min si necesario (máx 10 mg). Infusión: 0.4 mg/h","pediatrico":"0.01 mg/kg IV, repetir si necesario"},"presentaciones":["Ampollas 0.4 mg/mL","Spray nasal 4 mg/dosis (Narcan)"],"embarazo":"C","lactancia":"Datos insuficientes. Uso en emergencia justificado.","cuidadosEnfermeria":["VIDA MEDIA MÁS CORTA QUE MAYORÍA DE OPIOIDES: vigilar resedación","Monitorizar mínimo 2 horas post-administración","Titular dosis: objetivo es restaurar ventilación, no eliminar toda analgesia","Preparar infusión continua si opioide de larga acción (metadona, parches)","Vigilar síndrome abstinencia: agitación, vómitos, diaforesis, midriasis","Monitorizar FR, SatO2, nivel de conciencia","Ruta IV preferida en emergencia (más rápida)"],"farmacocinetica":{"inicioAccion":"IV: 1-2 min. IM: 2-5 min. Nasal: 3-5 min","picoAccion":"5-15 min","vidaMedia":"30-90 minutos","duracionAccion":"30-90 minutos (MÁS CORTA QUE LA MAYORÍA DE OPIOIDES)"},"almacenamiento":"Temperatura ambiente. Proteger de la luz.","unidadId":"u11","capituloId":"c11_01"},
{"id":"flumazenilo","nombre":"Flumazenilo","nombreGenerico":"Flumazenilo","nombresComerciales":["Anexate","Lanexat","Romazicon"],"familia":"Antídotos","clasificacion":"Antagonista de benzodiacepinas","mecanismoAccion":"Antagonista competitivo del sitio de unión de benzodiacepinas en el receptor GABA-A, revirtiendo sedación, depresión respiratoria y amnesia.","indicaciones":["Sobredosis de benzodiacepinas","Reversión de sedación consciente","Diagnóstico diferencial de coma"],"contraindicaciones":["Pacientes dependientes de benzodiacepinas (riesgo convulsiones)","Uso de benzodiacepinas para control de convulsiones","Intoxicación mixta con fármacos proconvulsivos (antidepresivos tricíclicos)"],"efectosAdversos":["Convulsiones (en dependientes)","Náuseas y vómitos","Agitación","Ansiedad","Arritmias"],"interacciones":["Benzodiacepinas: antagonismo","Antidepresivos tricíclicos: riesgo convulsiones"],"viaAdministracion":["IV"],"dosis":{"adulto":"0.2 mg IV en 15 seg. Repetir 0.2 mg cada 60 seg hasta respuesta. Máx: 3-5 mg total","pediatrico":"0.01 mg/kg (máx 0.2 mg/dosis)"},"presentaciones":["Ampollas 0.1 mg/mL (5 mL = 0.5 mg)"],"embarazo":"C","lactancia":"Probablemente compatible por vida media corta.","cuidadosEnfermeria":["Titular lentamente: evitar despertar brusco","Vida media MÁS CORTA que mayoría de BZD: vigilar resedación 2h","No usar si sospecha intoxicación por tricíclicos (precipita convulsiones)","Monitorizar nivel de conciencia y FR mínimo 2 horas","Preparar para posibles convulsiones","Tener diazepam disponible si se precipitan convulsiones"],"farmacocinetica":{"inicioAccion":"1-2 minutos","picoAccion":"6-10 minutos","vidaMedia":"40-80 minutos","duracionAccion":"45-90 minutos"},"almacenamiento":"Temperatura ambiente.","unidadId":"u11","capituloId":"c11_01"},
{"id":"n_acetilcisteina","nombre":"N-Acetilcisteína (NAC)","nombreGenerico":"N-acetilcisteína","nombresComerciales":["Fluimucil","Mucomyst","Acetadote"],"familia":"Antídotos","clasificacion":"Antídoto de paracetamol / mucolítico","mecanismoAccion":"Como antídoto: restaura los depósitos de glutatión hepático, detoxificando el metabolito tóxico del paracetamol (NAPQI). Como mucolítico: rompe puentes disulfuro del moco.","indicaciones":["Intoxicación por paracetamol","Mucolítico en enfermedades respiratorias","Protección renal por contraste (controversial)"],"contraindicaciones":["Hipersensibilidad (relativa, no impide uso en sobredosis)"],"efectosAdversos":["Náuseas y vómitos","Reacción anafilactoide (infusión rápida)","Rash","Broncoespasmo"],"interacciones":["Carbón activado: puede reducir absorción oral de NAC"],"viaAdministracion":["oral","IV","inhalatoria"],"dosis":{"adulto":"Intoxicación paracetamol IV (protocolo 21h): 150 mg/kg en 1h + 50 mg/kg en 4h + 100 mg/kg en 16h. Oral: 140 mg/kg carga + 70 mg/kg cada 4h x 17 dosis","pediatrico":"Misma dosis por kg que adulto"},"presentaciones":["Ampollas 200 mg/mL (10 mL = 2g)","Sobres efervescentes 200, 600 mg","Solución para nebulización 20%"],"embarazo":"B","lactancia":"Probablemente compatible.","cuidadosEnfermeria":["MÁXIMA EFICACIA dentro de 8h post-ingesta de paracetamol","Consultar nomograma de Rumack-Matthew para decidir tratamiento","Velocidad primera infusión: lenta para evitar reacción anafilactoide","Si reacción: detener infusión, antihistamínico, reiniciar más lento","Monitorizar función hepática seriada","Oral: sabor desagradable, mezclar con cola o jugo","La reacción anafilactoide NO es contraindicación para continuar en sobredosis grave"],"farmacocinetica":{"metabolismo":"Hepático: desacetilación a cisteína","vidaMedia":"5-6 horas","inicioAccion":"IV: inmediato"},"unidadId":"u11","capituloId":"c11_01"},
