{"id":"oxitocina","nombre":"Oxitocina","nombreGenerico":"Oxitocina sintética","nombresComerciales":["Pitocin","Syntocinon"],"familia":"Oxitócicos","clasificacion":"Hormona neurohipofisaria sintética","mecanismoAccion":"Se une a receptores de oxitocina en miometrio, estimulando contracciones uterinas rítmicas. También estimula eyección de leche.","indicaciones":["Inducción del parto","Estimulación del trabajo de parto","Hemorragia postparto","Facilitar lactancia"],"contraindicaciones":["Desproporción cefalopélvica","Placenta previa","Vasa previa","Prolapso de cordón","Sufrimiento fetal","Hipertonía uterina","Cesárea previa (precaución)"],"efectosAdversos":["Hiperestimulación uterina","Rotura uterina","Intoxicación hídrica (antidiuresis)","Hipotensión (IV rápido)","Náuseas"],"interacciones":["Prostaglandinas: efecto aditivo sobre útero","Vasopresores: potencia hipertensión","Anestesia caudal: puede potenciar hipotensión"],"viaAdministracion":["IV","IM"],"dosis":{"adulto":"Inducción: 0.5-2 mUI/min IV, titular cada 30-60 min. Hemorragia postparto: 10-40 UI en 1L de SF. IM: 10 UI","pediatrico":"No aplica"},"presentaciones":["Ampollas 5 UI/mL, 10 UI/mL"],"embarazo":"N/A","lactancia":"Compatible. Estimula eyección.","cuidadosEnfermeria":["SIEMPRE con bomba de infusión (nunca en bolo IV directo)","Monitorización fetal continua durante infusión","Vigilar actividad uterina: no más de 5 contracciones en 10 min","Suspender inmediatamente si hipertonía o sufrimiento fetal","Monitorizar PA, FC materna","Vigilar balance hídrico (efecto antidiurético)","Registrar frecuencia, duración e intensidad de contracciones","Fármaco de ALTO RIESGO: requiere doble verificación"],"farmacocinetica":{"vidaMedia":"3-5 minutos","inicioAccion":"IV: 1-3 min. IM: 3-5 min","duracionAccion":"IV: 30-60 min post-suspensión. IM: 2-3 horas"},"almacenamiento":"Refrigerar 2-8°C.","unidadId":"u07","capituloId":"c07_01"},
{"id":"furosemida","nombre":"Furosemida","nombreGenerico":"Furosemida","nombresComerciales":["Lasix","Seguril","Furesis"],"familia":"Diuréticos de asa","clasificacion":"Diurético de asa de alta eficacia","mecanismoAccion":"Inhibe el cotransportador Na-K-2Cl en el asa gruesa ascendente de Henle, produciendo diuresis potente con pérdida de sodio, potasio y agua.","indicaciones":["Insuficiencia cardíaca (edema)","Edema agudo de pulmón","Edema por cirrosis","Insuficiencia renal (mantener diuresis)","Hipercalcemia","Hipertensión (segunda línea)"],"contraindicaciones":["Anuria no responsiva a furosemida","Hipopotasemia severa","Hiponatremia severa","Deshidratación","Encefalopatía hepática"],"efectosAdversos":["Hipopotasemia","Hiponatremia","Deshidratación","Hipotensión","Alcalosis metabólica","Ototoxicidad (dosis altas IV)","Hiperuricemia","Hiperglucemia"],"interacciones":["Aminoglucósidos: potencia ototoxicidad","Digoxina: la hipopotasemia aumenta toxicidad","AINEs: reducen efecto diurético","Litio: aumenta toxicidad","IECA: potencia hipotensión"],"viaAdministracion":["oral","IV","IM"],"dosis":{"adulto":"Oral: 20-80 mg/día. IV: 20-40 mg bolo (máx 4 mg/min). EAP: 40-80 mg IV","pediatrico":"1-2 mg/kg/dosis oral. 1 mg/kg IV","ajusteRenal":"Puede necesitar dosis más altas en IR"},"presentaciones":["Comprimidos 40 mg","Ampollas 20 mg/2 mL"],"embarazo":"C","lactancia":"Se excreta en leche. Puede inhibir lactancia.","cuidadosEnfermeria":["Monitorizar potasio sérico regularmente","Administrar por la mañana (evitar nicturia)","IV: máx 4 mg/min (velocidades altas causan ototoxicidad)","Pesar al paciente diariamente (evaluar balance hídrico)","Monitorizar PA antes y después de administrar","Vigilar signos de deshidratación: sed, mucosas secas, hipotensión","Controlar glucemia en diabéticos","Educar sobre alimentos ricos en potasio: plátano, naranja, espinaca"],"farmacocinetica":{"absorcion":"Oral: 60-70%","metabolismo":"Mínimo","excrecion":"Renal 50% sin cambios","vidaMedia":"2 horas","inicioAccion":"Oral: 30-60 min. IV: 5 min","picoAccion":"Oral: 1-2h. IV: 30 min","duracionAccion":"Oral: 6-8h. IV: 2h"},"unidadId":"u02","capituloId":"c02_04"},
{"id":"dexametasona","nombre":"Dexametasona","nombreGenerico":"Fosfato sódico de dexametasona","nombresComerciales":["Decadrón","Fortecortin","Oradexon"],"familia":"Corticosteroides","clasificacion":"Glucocorticoide sintético de alta potencia","mecanismoAccion":"Se une a receptores glucocorticoides intracelulares, modulando transcripción génica. Suprime inflamación, respuesta inmune y actividad adrenal.","indicaciones":["Edema cerebral","Shock anafiláctico (coadyuvante)","Insuficiencia adrenal","Laringitis aguda severa","Náuseas por quimioterapia","Enfermedades autoinmunes","COVID-19 severo"],"contraindicaciones":["Infección sistémica no tratada","Vacunas con virus vivos (en dosis inmunosupresoras)"],"efectosAdversos":["Hiperglucemia","Inmunosupresión","Osteoporosis","Miopatía","Síndrome de Cushing","Úlcera péptica","Retraso cicatrización","Supresión adrenal","Trastornos psiquiátricos"],"interacciones":["AINEs: mayor riesgo úlcera","Anticoagulantes: efecto variable","Antidiabéticos: antagoniza","Rifampicina: reduce efecto","Vacunas vivas: contraindicadas"],"viaAdministracion":["oral","IV","IM"],"dosis":{"adulto":"Variable según indicación. Edema cerebral: 10 mg IV carga + 4 mg IV cada 6h. Antiemético: 8-20 mg IV","pediatrico":"Croup: 0.15-0.6 mg/kg dosis única. General: 0.1-0.3 mg/kg/día"},"presentaciones":["Comprimidos 0.5, 4, 8 mg","Ampollas 4 mg/mL, 8 mg/2 mL"],"embarazo":"C","lactancia":"Compatible a dosis bajas. Precaución a dosis altas.","cuidadosEnfermeria":["Monitorizar glucemia (hiperglucemia frecuente)","Administrar con protección gástrica si uso >3 días","NUNCA suspender bruscamente tras uso prolongado (crisis adrenal)","Vigilar signos de infección (inmunosupresión enmascara fiebre)","IV: puede administrarse en bolo lento","Pesar regularmente, vigilar edema","Educar sobre efectos a largo plazo si uso crónico"],"farmacocinetica":{"absorcion":"Oral: rápida","metabolismo":"Hepático","vidaMedia":"36-54 horas (biológica)","inicioAccion":"Oral: 1-2h. IV: rápido","duracionAccion":"36-72 horas"},"unidadId":"u06","capituloId":"c06_03"},
{"id":"acido_tranexamico","nombre":"Ácido Tranexámico","nombreGenerico":"Ácido tranexámico","nombresComerciales":["Transamin","Espercil","Lysteda"],"familia":"Hemostáticos","clasificacion":"Antifibrinolítico - análogo de lisina","mecanismoAccion":"Inhibe competitivamente la activación del plasminógeno a plasmina, previniendo la fibrinólisis y estabilizando el coágulo ya formado.","indicaciones":["Hemorragia postparto","Hemorragia traumática severa","Menorragia","Hemorragia dental en anticoagulados","Cirugía con alto riesgo hemorrágico"],"contraindicaciones":["Tromboembolismo activo","CID con fibrinólisis primaria","Hemorragia subaracnoidea","Insuficiencia renal grave"],"efectosAdversos":["Náuseas","Diarrea","Tromboembolismo (raro)","Convulsiones (dosis altas)","Trastornos visuales"],"interacciones":["Anticoagulantes: puede antagonizar","Factor IX: riesgo trombótico"],"viaAdministracion":["oral","IV"],"dosis":{"adulto":"IV: 1g en 10 min (trauma: dentro de 3h). Oral: 1-1.5g TID. Menorragia: 1g TID durante menstruación","pediatrico":"15-25 mg/kg/dosis cada 8h"},"presentaciones":["Comprimidos 500 mg","Ampollas 500 mg/5 mL"],"embarazo":"B","lactancia":"Compatible.","cuidadosEnfermeria":["En trauma: administrar DENTRO de las primeras 3 horas","Infundir IV lento (máx 100 mg/min)","Vigilar signos de tromboembolismo","Monitorizar función renal","Útil como buches en hemorragia dental: 10 mL al 5% cada 6h"],"farmacocinetica":{"absorcion":"Oral: 30-50%","excrecion":"Renal sin cambios 95%","vidaMedia":"2-3 horas","inicioAccion":"IV: inmediato"},"unidadId":"u10","capituloId":"c10_02"},
